// [Core.ICHIMOKULookback] bars, and [BadParam] for a parameter out of range or
// histories of different lengths.
func (c *Core) ICHIMOKUOpen(inHigh, inLow []float64, optInTenkanPeriod, optInKijunPeriod, optInSenkouBPeriod int) (*ICHIMOKUStream, float64, float64, float64, float64, error) {
	if !fitsInt32(optInTenkanPeriod) {
		return nil, 0, 0, 0, 0, BadParam
	}
	if !fitsInt32(optInKijunPeriod) {
		return nil, 0, 0, 0, 0, BadParam
	}
	if !fitsInt32(optInSenkouBPeriod) {
		return nil, 0, 0, 0, 0, BadParam
	}
	sp, err := c.ichimokuOpenInternal(inHigh, inLow, 0, int32(optInTenkanPeriod), int32(optInKijunPeriod), int32(optInSenkouBPeriod))
	if err != nil {
		return nil, 0, 0, 0, 0, err
	}
	return sp, sp.cur_outTenkanSen, sp.cur_outKijunSen, sp.cur_outSenkouSpanA, sp.cur_outSenkouSpanB, nil
}

// ICHIMOKUOpenAndFill opens a stream as [Core.ICHIMOKUOpen] does and also
// writes the outputs over the whole history, as [Core.ICHIMOKU] writes them for
// bars 0 through len(inHigh)-1, returning that range.
//
// Each output must hold len(inHigh) minus [Core.ICHIMOKULookback] values and
// share no memory with an input or another output.
//
// The errors are those of [Core.ICHIMOKUOpen], and [BadParam] for an output
// that is empty, too short or sharing memory.
func (c *Core) ICHIMOKUOpenAndFill(inHigh, inLow []float64, optInTenkanPeriod, optInKijunPeriod, optInSenkouBPeriod int, outTenkanSen, outKijunSen, outSenkouSpanA, outSenkouSpanB []float64) (*ICHIMOKUStream, OutRange, error) {
	if !fitsInt32(optInTenkanPeriod) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInKijunPeriod) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInSenkouBPeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.ichimokuLookback(int32(optInTenkanPeriod), int32(optInKijunPeriod), int32(optInSenkouBPeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inHigh)-lookback, 0)
	if len(outTenkanSen) == 0 || len(outTenkanSen) < outLen {
		return nil, OutRange{}, BadParam
	}
	if len(outKijunSen) == 0 || len(outKijunSen) < outLen {
		return nil, OutRange{}, BadParam
	}
	if len(outSenkouSpanA) == 0 || len(outSenkouSpanA) < outLen {
		return nil, OutRange{}, BadParam
	}
	if len(outSenkouSpanB) == 0 || len(outSenkouSpanB) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outTenkanSen, inHigh) || sameStart(outTenkanSen, inLow) || sameStart(outKijunSen, inHigh) || sameStart(outKijunSen, inLow) || sameStart(outSenkouSpanA, inHigh) || sameStart(outSenkouSpanA, inLow) || sameStart(outSenkouSpanB, inHigh) || sameStart(outSenkouSpanB, inLow) || sameStart(outTenkanSen, outKijunSen) || sameStart(outTenkanSen, outSenkouSpanA) || sameStart(outTenkanSen, outSenkouSpanB) || sameStart(outKijunSen, outSenkouSpanA) || sameStart(outKijunSen, outSenkouSpanB) || sameStart(outSenkouSpanA, outSenkouSpanB) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && (overlaps(outTenkanSen, inHigh) || overlaps(outTenkanSen, inLow) || overlaps(outKijunSen, inHigh) || overlaps(outKijunSen, inLow) || overlaps(outSenkouSpanA, inHigh) || overlaps(outSenkouSpanA, inLow) || overlaps(outSenkouSpanB, inHigh) || overlaps(outSenkouSpanB, inLow) || overlaps(outTenkanSen, outKijunSen) || overlaps(outTenkanSen, outSenkouSpanA) || overlaps(outTenkanSen, outSenkouSpanB) || overlaps(outKijunSen, outSenkouSpanA) || overlaps(outKijunSen, outSenkouSpanB) || overlaps(outSenkouSpanA, outSenkouSpanB)) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.ichimokuOpenAndFillInternal(inHigh, inLow, 0, int32(optInTenkanPeriod), int32(optInKijunPeriod), int32(optInSenkouBPeriod), &outBegIdx, &outNBElement, outTenkanSen, outKijunSen, outSenkouSpanA, outSenkouSpanB)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
